import java.util.*;class A{String s(boolean P,Scanner S){var a=new ArrayList<Integer>();var b=new ArrayList<Integer>();var c=new HashMap<Integer,Integer>();for(;S.hasNextInt();){a.add(S.nextInt());int x=S.nextInt();b.add(x);c.merge(x,1,(u,v)->u+v);}long r=0;if(P){Collections.sort(a);Collections.sort(b);for(int i=a.size();i-->0;)r+=Math.abs(a.get(i)-b.get(i));}else for(int x:a)r+=(long)x*c.getOrDefault(x,0);return r+"";}}
